usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.VectorStores.Files.New(
		context.TODO(),
		"vs_abc123",
		openai.VectorStoreFileNewParams{
			FileID: "string",
			ChunkingStrategy: openai.AutoChunkingStrategyRequestParam{Type: "auto"},
			Attributes: map[string]openai.VectorStoreFileAttributesValue{"key": "string"},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
